const output = [];
const seen = new Set();

/*
===========================================================
IPv4 validation
===========================================================
*/
function validIPv4(ip) {
    const p = String(ip || '').trim().split('.');

    if (p.length !== 4) {
        return false;
    }

    return p.every(x =>
        /^\d+$/.test(x) &&
        Number(x) >= 0 &&
        Number(x) <= 255
    );
}


/*
===========================================================
Extract IP
===========================================================
*/
function extractIP(text) {

    const ips = String(text || '').match(
        /(?:\d{1,3}\.){3}\d{1,3}/g
    ) || [];

    for (let i = ips.length - 1; i >= 0; i--) {

        if (validIPv4(ips[i])) {
            return ips[i];
        }
    }

    return '';
}


/*
===========================================================
Extract username
===========================================================
*/
function extractUsername(line) {

    let m;

    /*
    Accepted password for user
    */
    m = line.match(
        /Accepted\s+\S+\s+for\s+(\S+)\s+from\s+/i
    );

    if (m) {
        return m[1];
    }


    /*
    Failed password for user
    */
    m = line.match(
        /Failed\s+password\s+for\s+(\S+)\s+from\s+/i
    );

    if (m) {
        return m[1];
    }


    /*
    Failed password for invalid user
    */
    m = line.match(
        /Failed\s+password\s+for\s+invalid\s+user\s+(\S+)\s+from\s+/i
    );

    if (m) {
        return m[1];
    }


    /*
    Invalid user
    */
    m = line.match(
        /Invalid\s+user\s+(\S+)\s+from\s+/i
    );

    if (m) {
        return m[1];
    }


    /*
    PAM authentication failure
    */
    m = line.match(
        /\buser=(\S+)/i
    );

    if (m) {
        return m[1];
    }

    return '';
}


/*
===========================================================
Extract source port
===========================================================
*/
function extractPort(line) {

    const m = line.match(
        /\bport\s+(\d+)\b/i
    );

    return m ? Number(m[1]) : null;
}


/*
===========================================================
Classify SSH event
===========================================================
*/
function classifyEvent(line) {

    if (
        /sshd.*Accepted\s+password/i.test(line) ||
        /sshd.*Accepted\s+publickey/i.test(line) ||
        /sshd.*Accepted\s+keyboard-interactive/i.test(line)
    ) {
        return 'SSH_LOGIN_SUCCESS';
    }

    if (/sshd.*Failed\s+password/i.test(line)) {
        return 'SSH_FAILED_PASSWORD';
    }

    if (/sshd.*Invalid\s+user/i.test(line)) {
        return 'SSH_INVALID_USER';
    }

    if (/sshd.*authentication\s+failure/i.test(line)) {
        return 'SSH_AUTH_FAILURE';
    }

    return 'SSH_OTHER';
}


/*
===========================================================
Extract EVENT_EPOCH
===========================================================
*/
function extractEpoch(text) {

    const m = String(text || '').match(
        /EVENT_EPOCH=(\d+)/i
    );

    if (!m) {
        return null;
    }

    const value = Number(m[1]);

    return Number.isFinite(value)
        ? value
        : null;
}


/*
===========================================================
Extract SOURCE_IP from SECURITY_EVENT metadata
===========================================================
*/
function extractSourceIP(text) {

    const m = String(text || '').match(
        /SOURCE_IP=([^|]+)/i
    );

    if (m) {
        const ip = m[1].trim();

        if (validIPv4(ip)) {
            return ip;
        }
    }

    return extractIP(text);
}


/*
===========================================================
Extract LOG_FILE
===========================================================
*/
function extractLogFile(text) {

    const m = String(text || '').match(
        /LOG_FILE=([^|]+)$/i
    );

    return m
        ? m[1].trim()
        : '/var/log/secure';
}


/*
===========================================================
Clean SECURITY_EVENT metadata
===========================================================
*/
function cleanLogLine(text) {

    return String(text || '')
        .replace(/\|SOURCE_IP=[^|]+/i, '')
        .replace(/\|EVENT_EPOCH=\d+/i, '')
        .replace(/\|LOG_FILE=.*$/i, '')
        .trim();
}


/*
===========================================================
Extract Ansible hostname
===========================================================
*/
function extractHost(line) {

    const m = String(line || '').match(
        /^([^\s|]+)\s+\|\s+(SUCCESS|CHANGED|FAILED|UNREACHABLE!?)/i
    );

    return m
        ? m[1]
        : '';
}


/*
===========================================================
PROCESS ITEMS
===========================================================
*/
for (const item of items) {

    const data = item.json || {};

    let stdout = String(data.stdout || '');

    const stderr = String(data.stderr || '');

    const ansibleCode = data.code ?? null;


    /*
    -------------------------------------------------------
    Important:
    Convert literal \n into real newlines too.
    This handles cases where Ansible output is escaped.
    -------------------------------------------------------
    */
    stdout = stdout
        .replace(/\\r\\n/g, '\n')
        .replace(/\\n/g, '\n')
        .replace(/\\r/g, '\r');


    /*
    -------------------------------------------------------
    Current Ansible host
    -------------------------------------------------------
    */
    let currentHost = 'unknown';


    /*
    -------------------------------------------------------
    Split stdout
    -------------------------------------------------------
    */
    const lines = stdout.split(/\r?\n/);


    for (const raw of lines) {

        const line = raw.trim();

        if (!line) {
            continue;
        }


        /*
        ---------------------------------------------------
        Detect Ansible hostname
        ---------------------------------------------------
        */
        const host = extractHost(line);

        if (host) {
            currentHost = host;
        }


        /*
        ---------------------------------------------------
        Find SECURITY_EVENT
        ---------------------------------------------------
        */
        const marker = 'SECURITY_EVENT|';

        const position = line.indexOf(marker);

        if (position === -1) {
            continue;
        }


        /*
        ---------------------------------------------------
        Extract event payload
        ---------------------------------------------------
        */
        const eventText =
            line.substring(position + marker.length).trim();


        if (!eventText) {
            continue;
        }


        /*
        ---------------------------------------------------
        Source IP
        ---------------------------------------------------
        */
        const sourceIP =
            extractSourceIP(eventText);


        /*
        IMPORTANT:
        DO NOT reject private IP here.

        This node is only PARSING.
        Filtering will happen in the next node.
        ---------------------------------------------------
        */
        if (!validIPv4(sourceIP)) {
            continue;
        }


        /*
        ---------------------------------------------------
        Epoch
        ---------------------------------------------------
        */
        const epoch =
            extractEpoch(eventText);


        /*
        ---------------------------------------------------
        Original log
        ---------------------------------------------------
        */
        const logLine =
            cleanLogLine(eventText);


        if (!logLine) {
            continue;
        }


        /*
        ---------------------------------------------------
        Event type
        ---------------------------------------------------
        */
        const eventType =
            classifyEvent(logLine);


        /*
        ---------------------------------------------------
        Username
        ---------------------------------------------------
        */
        const username =
            extractUsername(logLine);


        /*
        ---------------------------------------------------
        Source port
        ---------------------------------------------------
        */
        const sourcePort =
            extractPort(logLine);


        /*
        ---------------------------------------------------
        Log timestamp
        ---------------------------------------------------
        */
        const logTime =
            logLine.substring(0, 15);


        /*
        ---------------------------------------------------
        Log file
        ---------------------------------------------------
        */
        const logFile =
            extractLogFile(eventText);


        /*
        ---------------------------------------------------
        Deduplication
        ---------------------------------------------------
        */
        const key = [
            currentHost,
            epoch || '',
            sourceIP,
            username,
            eventType,
            sourcePort || '',
            logLine
        ].join('|');


        if (seen.has(key)) {
            continue;
        }

        seen.add(key);


        /*
        ---------------------------------------------------
        OUTPUT
        ---------------------------------------------------
        */
        output.push({
            json: {

                hostname:
                    currentHost,

                event_type:
                    eventType,

                source_ip:
                    sourceIP,

                username:
                    username,

                log_time:
                    logTime,

                event_epoch:
                    epoch,

                log_file:
                    logFile,

                log_line:
                    logLine,

                raw_log:
                    logLine,

                source_port:
                    sourcePort,

                destination_port:
                    22,

                target_service:
                    'SSH',

                ansible_rc:
                    ansibleCode,

                ansible_stderr:
                    stderr
            }
        });
    }
}


/*
===========================================================
Sort chronologically
===========================================================
*/
output.sort((a, b) => {

    return Number(a.json.event_epoch || 0) -
           Number(b.json.event_epoch || 0);

});


return output;

const seen = new Set();
const out = [];

for (const item of items) {
  const r = item.json || {};
  if (!r.source_ip || !r.event_epoch) continue;

  const key = [
    r.hostname || '',
    r.event_epoch || '',
    r.event_type || '',
    r.source_ip || '',
    r.username || '',
    r.log_line || ''
  ].join('|');

  if (seen.has(key)) continue;
  seen.add(key);

  out.push({
    json: {
      ...r,
      source_ip: String(r.source_ip).trim(),
      event_type: r.event_type || 'SSH_SECURITY_EVENT',
      target_service: 'SSH',
      destination_port: 22
    }
  });
}

return out;

const geo = $json.geo_results || [];
const map = new Map(
  geo.map(g => [
    g.query,
    {
      country: g.country || 'Unknown',
      country_code: g.countryCode || '',
      region: g.regionName || '',
      city: g.city || '',
      isp: g.isp || '',
      organization: g.org || ''
    }
  ])
);

// Private / reserved ranges: RFC1918, loopback, link-local, CGNAT.
// A failed login from one of these is an internal user, not an external attacker.
const isPrivate = ip =>
  /^(0\.|10\.|127\.|169\.254\.|192\.168\.|100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.|172\.(1[6-9]|2\d|3[01])\.)/.test(String(ip || ''));

const out = [];

for (const item of $('Normalize and Deduplicate').all()) {
  const r = item.json;

  // Only genuine external/public-IP login attempts are security events worth storing.
  if (isPrivate(r.source_ip)) continue;

  const g = map.get(r.source_ip) || {};

  // If GeoIP explicitly identifies India, exclude it.
  // If the GeoIP service returns no country, retain the event rather than silently losing a security event.
  if (String(g.country_code || '').toUpperCase() === 'IN') continue;

  const severity =
    ['SSH_FAILED_PASSWORD', 'SSH_INVALID_USER', 'SSH_AUTH_FAILURE'].includes(r.event_type)
      ? 'HIGH'
      : 'MEDIUM';

  out.push({
    json: {
      ...r,
      ...g,
      country: g.country || 'Unknown',
      country_code: g.country_code || '',
      is_non_india: String(g.country_code || '').toUpperCase() !== 'IN',
      detected_at: new Date().toISOString(),
      destination_port: 22,
      target_service: 'SSH',
      alert_severity: severity
    }
  });
}

return out;

const rows = items.map(i => i.json);
if (!rows.length) return [];

const esc = v => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const html =
  '<html><body>' +
  '<h2>Chennai /var/log/secure - Non-India SSH Security Report</h2>' +
  '<p><b>Monitoring window:</b> Last 5 days</p>' +
  '<p><b>Events detected:</b> ' + rows.length + '</p>' +
  '<table border="1" cellpadding="6" cellspacing="0">' +
  '<tr><th>Server</th><th>Event Time</th><th>Log File</th><th>Source IP</th><th>Country</th><th>City</th><th>Event</th><th>User</th><th>Source Port</th><th>Severity</th><th>Log</th></tr>' +
  rows.map(r =>
    '<tr>' +
    '<td>' + esc(r.hostname) + '</td>' +
    '<td>' + esc(r.event_epoch ? new Date(Number(r.event_epoch) * 1000).toISOString() : r.log_time) + '</td>' +
    '<td>' + esc(r.log_file) + '</td>' +
    '<td>' + esc(r.source_ip) + '</td>' +
    '<td>' + esc(r.country) + '</td>' +
    '<td>' + esc(r.city) + '</td>' +
    '<td>' + esc(r.event_type) + '</td>' +
    '<td>' + esc(r.username) + '</td>' +
    '<td>' + esc(r.source_port) + '</td>' +
    '<td>' + esc(r.alert_severity) + '</td>' +
    '<td>' + esc(r.raw_log) + '</td>' +
    '</tr>'
  ).join('') +
  '</table></body></html>';

return [{
  json: {
    event_count: rows.length,
    monitoring_window_days: 5,
    events: rows,
    html
  }
}];

const report = $('Create Security Report').first().json;

const events = Array.isArray(report.events)
    ? report.events
    : [];

/*
 * ---------------------------------------------------------
 * 32-bit hash function
 * ---------------------------------------------------------
 * Used only as a deterministic event fingerprint.
 * This does NOT provide cryptographic security.
 * It is suitable for duplicate-event detection.
 * ---------------------------------------------------------
 */
function hash32(str, seed) {

    let h = seed >>> 0;

    for (let i = 0; i < str.length; i++) {

        h ^= str.charCodeAt(i);

        h = Math.imul(h, 16777619) >>> 0;

        h ^= h >>> 13;
        h = Math.imul(h, 2246822519) >>> 0;
        h ^= h >>> 16;
    }

    return h.toString(16).padStart(8, '0');
}


/*
 * ---------------------------------------------------------
 * Generate 64-character fingerprint
 * ---------------------------------------------------------
 */
function createFingerprint(value) {

    const seeds = [
        2166136261,
        3432918353,
        123456789,
        362436069,
        521288629,
        88675123,
        5783321,
        6615241
    ];

    return seeds
        .map(seed => hash32(value, seed))
        .join('');
}


/*
 * ---------------------------------------------------------
 * Process events
 * ---------------------------------------------------------
 */

const output = [];
const seen = new Set();

for (const event of events) {

    const r = event || {};

    /*
     * Build a stable event key.
     *
     * Do NOT include detected_at because that changes
     * every workflow execution and would create duplicates.
     */

    const fingerprintSource = [
        String(r.hostname || '').trim(),
        String(r.event_epoch || '').trim(),
        String(r.source_ip || '').trim(),
        String(r.source_port || '').trim(),
        String(r.destination_port || '').trim(),
        String(r.event_type || '').trim(),
        String(r.username || '').trim(),
        String(r.log_file || '').trim(),
        String(r.log_line || '').trim()
    ].join('|');


    /*
     * Generate fingerprint
     */

    const eventHash = createFingerprint(fingerprintSource);


    /*
     * Prevent duplicates inside the same execution
     */

    if (seen.has(eventHash)) {
        continue;
    }

    seen.add(eventHash);


    /*
     * Return original event + fingerprint
     */

    output.push({
        json: {
            ...r,

            event_hash: eventHash,

            fingerprint_source: fingerprintSource
        }
    });
}


/*
 * ---------------------------------------------------------
 * Return results
 * ---------------------------------------------------------
 */

return output;

// ============================================================
// SSH SECURITY INCIDENT SUMMARY
// One incident per unique Source IP
// Multiple events from the same IP = ONE incident
// Multiple different IPs = Multiple incidents
// ============================================================

// Get all SSH events
const eventItems = $('Create Event Fingerprints1').all();

// Get all GeoIP results
const geoItems = $('GeoIP Lookup - IP API').all();


// ------------------------------------------------------------
// Build GeoIP map
// IP-API normally returns the IP in "query"
// ------------------------------------------------------------
const geoMap = new Map();

for (const item of geoItems) {
    const geo = item.json || {};

    const ip =
        geo.query ||
        geo.ip ||
        geo.source_ip ||
        '';

    if (ip) {
        geoMap.set(String(ip).trim(), geo);
    }
}


// ------------------------------------------------------------
// Keep only ONE event per Source IP
// ------------------------------------------------------------
const uniqueIPs = new Map();

for (const item of eventItems) {

    const event = item.json || {};

    const sourceIP = String(event.source_ip || '').trim();

    // Ignore events without source IP
    if (!sourceIP) {
        continue;
    }

    // If this IP already exists, skip it
    if (uniqueIPs.has(sourceIP)) {
        continue;
    }

    // --------------------------------------------------------
    // Get GeoIP information for this IP
    // --------------------------------------------------------
    const geo = geoMap.get(sourceIP) || {};

    const country =
        geo.country ||
        event.country ||
        '';

    const countryCode =
        geo.countryCode ||
        event.countryCode ||
        '';

    const region =
        geo.region ||
        event.region ||
        '';

    const regionName =
        geo.regionName ||
        event.regionName ||
        '';

    const city =
        geo.city ||
        event.city ||
        '';

    const isp =
        geo.isp ||
        event.isp ||
        '';

    const organization =
        geo.organization ||
        event.organization ||
        '';


    // --------------------------------------------------------
    // Determine whether source is outside India
    // --------------------------------------------------------
    const isNonIndia =
        countryCode.toUpperCase() !== 'IN';


    // --------------------------------------------------------
    // Store ONE incident for this IP
    // --------------------------------------------------------
    uniqueIPs.set(sourceIP, {

        hostname: event.hostname || '',

        event_type:
            event.event_type ||
            'SSH_SECURITY_EVENT',

        source_ip: sourceIP,

        username:
            event.username ||
            '',

        log_time:
            event.log_time ||
            '',

        log_line:
            event.log_line ||
            '',

        is_non_india: isNonIndia,

        alert_severity:
            event.alert_severity ||
            'HIGH',

        country: country,

        countryCode: countryCode,

        region: region,

        regionName: regionName,

        city: city,

        isp: isp,

        organization: organization
    });
}


// ------------------------------------------------------------
// Convert Map to array
// ------------------------------------------------------------
const incidents = Array.from(uniqueIPs.values());


// ------------------------------------------------------------
// IMPORTANT:
// Show only NON-INDIA incidents
// ------------------------------------------------------------
const nonIndiaIncidents = incidents.filter(
    incident => incident.is_non_india === true
);


// ------------------------------------------------------------
// Return ONE n8n item containing all unique IP incidents
// ------------------------------------------------------------
return [
    {
        json: {

            // Number of unique external IPs
            total_events: nonIndiaIncidents.length,

            // Number of all unique IPs before filtering
            total_unique_ips: incidents.length,

            // Number of unique non-India IPs
            non_india_events: nonIndiaIncidents.length,

            // Actual incident details
            events: nonIndiaIncidents
        }
    }
];

// Create Event Fingerprints
// Input: multiple SSH security events
// Output: one item per unique security event

const output = [];
const seen = new Set();

/*
 * 32-bit deterministic hash
 * Used only for duplicate-event detection.
 */
function hash32(str, seed) {
    let h = seed >>> 0;

    for (let i = 0; i < str.length; i++) {
        h ^= str.charCodeAt(i);
        h = Math.imul(h, 16777619) >>> 0;
        h ^= h >>> 13;
        h = Math.imul(h, 2246822519) >>> 0;
        h ^= h >>> 16;
    }

    return h.toString(16).padStart(8, '0');
}

/*
 * Create 64-character event fingerprint
 */
function createFingerprint(value) {
    const seeds = [
        2166136261,
        3432918353,
        123456789,
        362436069,
        521288629,
        88675123,
        5783321,
        6615241
    ];

    return seeds
        .map(seed => hash32(value, seed))
        .join('');
}

/*
 * Process the input items directly.
 */
for (const item of items) {

    const r = item.json || {};

    /*
     * Stable fingerprint source.
     *
     * detected_at is intentionally NOT included because
     * it changes on every workflow execution.
     */
    const fingerprintSource = [
        String(r.hostname || '').trim(),
        String(r.event_epoch || '').trim(),
        String(r.source_ip || '').trim(),
        String(r.source_port || '').trim(),
        String(r.destination_port || '').trim(),
        String(r.event_type || '').trim(),
        String(r.username || '').trim(),
        String(r.log_file || '').trim(),
        String(r.log_line || '').trim()
    ].join('|');

    /*
     * Generate fingerprint
     */
    const eventHash = createFingerprint(fingerprintSource);

    /*
     * Remove duplicate events during this execution
     */
    if (seen.has(eventHash)) {
        continue;
    }

    seen.add(eventHash);

    /*
     * Return event + fingerprint
     */
    output.push({
        json: {
            ...r,
            event_hash: eventHash,
            fingerprint_source: fingerprintSource
        }
    });
}

return output;
